algorithms.pseudocode:
FLOYD-WARSHALL(W):
  D <- W
  for k = 0..n-1:
    for i = 0..n-1:
      for j = 0..n-1:
        D[i,j] <- min(D[i,j], D[i,k]+D[k,j])
  return D

KARP-MCM(W):
  D[0,:] <- 0
  for k = 1..n:
    for i = 0..n-1:
      D[k,i] <- min_j(D[k-1,j]+W[j,i])
  return min_i max_{k<n} (D[n,i]-D[k,i])/(n-k)
